type
  KalynaCtx*[B: static int] = object
    evenKey*: array[B, uint64]
    oddKey*: array[B, uint64]

# --- 도움말 템플릿 (인라인 캐스팅 오버헤드 방지) ---
template toByte(x: any): uint8 = cast[uint8](x)

# --- Key Generation & Block Operations ---

template makeOddKey*[NB: static int](evenKey: array[NB, uint64], oddKey: var array[NB, uint64]) {.inline.} =
  when BE:
    when NB == 2:
      oddKey[0] = (evenKey[1] shl 8) or (evenKey[0] shr 56)
      oddKey[1] = (evenKey[0] shl 8) or (evenKey[1] shr 56)
    elif NB == 4:
      oddKey[0] = (evenKey[2] shl 40) or (evenKey[1] shr 24)
      oddKey[1] = (evenKey[3] shl 40) or (evenKey[2] shr 24)
      oddKey[2] = (evenKey[0] shl 40) or (evenKey[3] shr 24)
      oddKey[3] = (evenKey[1] shl 40) or (evenKey[0] shr 24)
    elif NB == 8:
      oddKey[0] = (evenKey[3] shl 40) or (evenKey[2] shr 24)
      oddKey[1] = (evenKey[4] shl 40) or (evenKey[3] shr 24)
      oddKey[2] = (evenKey[5] shl 40) or (evenKey[4] shr 24)
      oddKey[3] = (evenKey[6] shl 40) or (evenKey[5] shr 24)
      oddKey[4] = (evenKey[7] shl 40) or (evenKey[6] shr 24)
      oddKey[5] = (evenKey[0] shl 40) or (evenKey[7] shr 24)
      oddKey[6] = (evenKey[1] shl 40) or (evenKey[0] shr 24)
      oddKey[7] = (evenKey[2] shl 40) or (evenKey[1] shr 24)
    else:
      {.error: "Unsupported NB size".}
  else:
    const U = when NB == 2: 16 elif NB == 4: 32 elif NB == 8: 64 else: -1
    const V = when NB == 2: 7  elif NB == 4: 11 elif NB == 8: 19 else: -1

    copyMem(addr oddKey[0], addr evenKey[V], U - V)
    copyMem(addr oddKey[U - V], addr evenKey[0], V)

template swapBlocks*[NB: static int](k: var array[NB, uint64]) {.inline.} =
  let t = k[0]
  k[0] = k[1]
  when NB > 2:
    k[1] = k[2]
    k[2] = k[3]
  when NB > 4:
    k[3] = k[4]
    k[4] = k[5]
    k[5] = k[6]
    k[6] = k[7]
  k[NB - 1] = t

template addKey*[B: static int](x: array[B, uint64], y: var array[B, uint64], k: array[B, uint64]): void =
  for i in static(0 ..< B):
    y[i] = x[i] + k[i]

template subKey*[B: static int](x: array[B, uint64], y: var array[B, uint64], k: array[B, uint64]): void =
  for i in static(0 ..< B):
    y[i] = x[i] - k[i]

template addConstant*[B: static int](input: array[B, uint64], output: var array[B, uint64], constant: uint64): void =
  for i in static(0 ..< B):
    output[i] = input[i] + constant

template g0128*(x: array[2, uint64], y: var array[2, uint64]) =
  y[0] = ET[0][int(x[0] and 0xFF'u64)] xor
         ET[1][int((x[0] shr 8) and 0xFF'u64)] xor
         ET[2][int((x[0] shr 16) and 0xFF'u64)] xor
         ET[3][int((x[0] shr 24) and 0xFF'u64)] xor
         ET[4][int((x[1] shr 32) and 0xFF'u64)] xor
         ET[5][int((x[1] shr 40) and 0xFF'u64)] xor
         ET[6][int((x[1] shr 48) and 0xFF'u64)] xor
         ET[7][int((x[1] shr 56) and 0xFF'u64)]
  y[1] = ET[0][int(x[1] and 0xFF'u64)] xor
         ET[1][int((x[1] shr 8) and 0xFF'u64)] xor
         ET[2][int((x[1] shr 16) and 0xFF'u64)] xor
         ET[3][int((x[1] shr 24) and 0xFF'u64)] xor
         ET[4][int((x[0] shr 32) and 0xFF'u64)] xor
         ET[5][int((x[0] shr 40) and 0xFF'u64)] xor
         ET[6][int((x[0] shr 48) and 0xFF'u64)] xor
         ET[7][int((x[0] shr 56) and 0xFF'u64)]

template g0256*(x: array[4, uint64], y: var array[4, uint64]) =
  y[0] = ET[0][int(x[0] and 0xFF'u64)] xor
         ET[1][int((x[0] shr 8) and 0xFF'u64)] xor
         ET[2][int((x[3] shr 16) and 0xFF'u64)] xor
