         ET[6][int((x[7] shr 48) and 0xFF'u64)] xor
         ET[7][int((x[6] shr 56) and 0xFF'u64)]
  y[6] = ET[0][int(x[6] and 0xFF'u64)] xor
         ET[1][int((x[5] shr 8) and 0xFF'u64)] xor
         ET[2][int((x[4] shr 16) and 0xFF'u64)] xor
         ET[3][int((x[3] shr 24) and 0xFF'u64)] xor
         ET[4][int((x[2] shr 32) and 0xFF'u64)] xor
         ET[5][int((x[1] shr 40) and 0xFF'u64)] xor
         ET[6][int((x[0] shr 48) and 0xFF'u64)] xor
         ET[7][int((x[7] shr 56) and 0xFF'u64)]
  y[7] = ET[0][int(x[7] and 0xFF'u64)] xor
         ET[1][int((x[6] shr 8) and 0xFF'u64)] xor
         ET[2][int((x[5] shr 16) and 0xFF'u64)] xor
         ET[3][int((x[4] shr 24) and 0xFF'u64)] xor
