         ET[5][int((x[2] shr 40) and 0xFF'u64)] xor
         ET[6][int((x[1] shr 48) and 0xFF'u64)] xor
         ET[7][int((x[0] shr 56) and 0xFF'u64)]

# --- GL Functions (with Addition Key) ---

template gl128*(x: array[2, uint64], y: var array[2, uint64], k: array[2, uint64]) =
  y[0] = k[0] + (ET[0][int(x[0] and 0xFF'u64)] xor ET[1][int((x[0] shr 8) and 0xFF'u64)] xor ET[2][int((x[0] shr 16) and 0xFF'u64)] xor ET[3][int((x[0] shr 24) and 0xFF'u64)] xor ET[4][int((x[1] shr 32) and 0xFF'u64)] xor ET[5][int((x[1] shr 40) and 0xFF'u64)] xor ET[6][int((x[1] shr 48) and 0xFF'u64)] xor ET[7][int((x[1] shr 56) and 0xFF'u64)])
  y[1] = k[1] + (ET[0][int(x[1] and 0xFF'u64)] xor ET[1][int((x[1] shr 8) and 0xFF'u64)] xor ET[2][int((x[1] shr 16) and 0xFF'u64)] xor ET[3][int((x[1] shr 24) and 0xFF'u64)] xor ET[4][int((x[0] shr 32) and 0xFF'u64)] xor ET[5][int((x[0] shr 40) and 0xFF'u64)] xor ET[6][int((x[0] shr 48) and 0xFF'u64)] xor ET[7][int((x[0] shr 56) and 0xFF'u64)])

template gl256*(x: array[4, uint64], y: var array[4, uint64], k: array[4, uint64]) =
  y[0] = k[0] + (ET[0][int(x[0] and 0xFF'u64)] xor ET[1][int((x[0] shr 8) and 0xFF'u64)] xor ET[2][int((x[3] shr 16) and 0xFF'u64)] xor ET[3][int((x[3] shr 24) and 0xFF'u64)] xor ET[4][int((x[2] shr 32) and 0xFF'u64)] xor ET[5][int((x[2] shr 40) and 0xFF'u64)] xor ET[6][int((x[1] shr 48) and 0xFF'u64)] xor ET[7][int((x[1] shr 56) and 0xFF'u64)])
  y[1] = k[1] + (ET[0][int(x[1] and 0xFF'u64)] xor ET[1][int((x[1] shr 8) and 0xFF'u64)] xor ET[2][int((x[0] shr 16) and 0xFF'u64)] xor ET[3][int((x[0] shr 24) and 0xFF'u64)] xor ET[4][int((x[3] shr 32) and 0xFF'u64)] xor ET[5][int((x[3] shr 40) and 0xFF'u64)] xor ET[6][int((x[2] shr 48) and 0xFF'u64)] xor ET[7][int((x[2] shr 56) and 0xFF'u64)])
  y[2] = k[2] + (ET[0][int(x[2] and 0xFF'u64)] xor ET[1][int((x[2] shr 8) and 0xFF'u64)] xor ET[2][int((x[1] shr 16) and 0xFF'u64)] xor ET[3][int((x[1] shr 24) and 0xFF'u64)] xor ET[4][int((x[0] shr 32) and 0xFF'u64)] xor ET[5][int((x[0] shr 40) and 0xFF'u64)] xor ET[6][int((x[3] shr 48) and 0xFF'u64)] xor ET[7][int((x[3] shr 56) and 0xFF'u64)])
  y[3] = k[3] + (ET[0][int(x[3] and 0xFF'u64)] xor ET[1][int((x[3] shr 8) and 0xFF'u64)] xor ET[2][int((x[2] shr 16) and 0xFF'u64)] xor ET[3][int((x[2] shr 24) and 0xFF'u64)] xor ET[4][int((x[1] shr 32) and 0xFF'u64)] xor ET[5][int((x[1] shr 40) and 0xFF'u64)] xor ET[6][int((x[0] shr 48) and 0xFF'u64)] xor ET[7][int((x[0] shr 56) and 0xFF'u64)])

template gl512*(x: array[8, uint64], y: var array[8, uint64], k: array[8, uint64]) =
  y[0] = k[0] + (ET[0][int(x[0] and 0xFF'u64)] xor ET[1][int((x[7] shr 8) and 0xFF'u64)] xor ET[2][int((x[6] shr 16) and 0xFF'u64)] xor ET[3][int((x[5] shr 24) and 0xFF'u64)] xor ET[4][int((x[4] shr 32) and 0xFF'u64)] xor ET[5][int((x[3] shr 40) and 0xFF'u64)] xor ET[6][int((x[2] shr 48) and 0xFF'u64)] xor ET[7][int((x[1] shr 56) and 0xFF'u64)])
  y[1] = k[1] + (ET[0][int(x[1] and 0xFF'u64)] xor ET[1][int((x[0] shr 8) and 0xFF'u64)] xor ET[2][int((x[7] shr 16) and 0xFF'u64)] xor ET[3][int((x[6] shr 24) and 0xFF'u64)] xor ET[4][int((x[5] shr 32) and 0xFF'u64)] xor ET[5][int((x[4] shr 40) and 0xFF'u64)] xor ET[6][int((x[3] shr 48) and 0xFF'u64)] xor ET[7][int((x[2] shr 56) and 0xFF'u64)])
  y[2] = k[2] + (ET[0][int(x[2] and 0xFF'u64)] xor ET[1][int((x[1] shr 8) and 0xFF'u64)] xor ET[2][int((x[0] shr 16) and 0xFF'u64)] xor ET[3][int((x[7] shr 24) and 0xFF'u64)] xor ET[4][int((x[6] shr 32) and 0xFF'u64)] xor ET[5][int((x[5] shr 40) and 0xFF'u64)] xor ET[6][int((x[4] shr 48) and 0xFF'u64)] xor ET[7][int((x[3] shr 56) and 0xFF'u64)])
