# --- IGL Functions (Inverse T-Table with Subtraction Key) ---

template igl128*(x: array[2, uint64], y: var array[2, uint64], k: array[2, uint64]) =
  y[0] = (uint64(DS[0][int(x[0] and 0xFF'u64)]) xor
         (uint64(DS[1][int((x[0] shr 8) and 0xFF'u64)]) shl 8) xor
         (uint64(DS[2][int((x[0] shr 16) and 0xFF'u64)]) shl 16) xor
         (uint64(DS[3][int((x[0] shr 24) and 0xFF'u64)]) shl 24) xor
         (uint64(DS[0][int((x[1] shr 32) and 0xFF'u64)]) shl 32) xor
         (uint64(DS[1][int((x[1] shr 40) and 0xFF'u64)]) shl 40) xor
         (uint64(DS[2][int((x[1] shr 48) and 0xFF'u64)]) shl 48) xor
         (uint64(DS[3][int((x[1] shr 56) and 0xFF'u64)]) shl 56)) - k[0]
  y[1] = (uint64(DS[0][int(x[1] and 0xFF'u64)]) xor
         (uint64(DS[1][int((x[1] shr 8) and 0xFF'u64)]) shl 8) xor
         (uint64(DS[2][int((x[1] shr 16) and 0xFF'u64)]) shl 16) xor
         (uint64(DS[3][int((x[1] shr 24) and 0xFF'u64)]) shl 24) xor
         (uint64(DS[0][int((x[0] shr 32) and 0xFF'u64)]) shl 32) xor
         (uint64(DS[1][int((x[0] shr 40) and 0xFF'u64)]) shl 40) xor
         (uint64(DS[2][int((x[0] shr 48) and 0xFF'u64)]) shl 48) xor
         (uint64(DS[3][int((x[0] shr 56) and 0xFF'u64)]) shl 56)) - k[1]

template igl256*(x: array[4, uint64], y: var array[4, uint64], k: array[4, uint64]) =
  y[0] = (uint64(DS[0][int(x[0] and 0xFF'u64)]) xor
         (uint64(DS[1][int((x[0] shr 8) and 0xFF'u64)]) shl 8) xor
         (uint64(DS[2][int((x[1] shr 16) and 0xFF'u64)]) shl 16) xor
         (uint64(DS[3][int((x[1] shr 24) and 0xFF'u64)]) shl 24) xor
         (uint64(DS[0][int((x[2] shr 32) and 0xFF'u64)]) shl 32) xor
         (uint64(DS[1][int((x[2] shr 40) and 0xFF'u64)]) shl 40) xor
         (uint64(DS[2][int((x[3] shr 48) and 0xFF'u64)]) shl 48) xor
         (uint64(DS[3][int((x[3] shr 56) and 0xFF'u64)]) shl 56)) - k[0]
  y[1] = (uint64(DS[0][int(x[1] and 0xFF'u64)]) xor
         (uint64(DS[1][int((x[1] shr 8) and 0xFF'u64)]) shl 8) xor
         (uint64(DS[2][int((x[2] shr 16) and 0xFF'u64)]) shl 16) xor
         (uint64(DS[3][int((x[2] shr 24) and 0xFF'u64)]) shl 24) xor
         (uint64(DS[0][int((x[3] shr 32) and 0xFF'u64)]) shl 32) xor
         (uint64(DS[1][int((x[3] shr 40) and 0xFF'u64)]) shl 40) xor
         (uint64(DS[2][int((x[0] shr 48) and 0xFF'u64)]) shl 48) xor
         (uint64(DS[3][int((x[0] shr 56) and 0xFF'u64)]) shl 56)) - k[1]
  y[2] = (uint64(DS[0][int(x[2] and 0xFF'u64)]) xor
         (uint64(DS[1][int((x[2] shr 8) and 0xFF'u64)]) shl 8) xor
         (uint64(DS[2][int((x[3] shr 16) and 0xFF'u64)]) shl 16) xor
         (uint64(DS[3][int((x[3] shr 24) and 0xFF'u64)]) shl 24) xor
         (uint64(DS[0][int((x[0] shr 32) and 0xFF'u64)]) shl 32) xor
         (uint64(DS[1][int((x[0] shr 40) and 0xFF'u64)]) shl 40) xor
         (uint64(DS[2][int((x[1] shr 48) and 0xFF'u64)]) shl 48) xor
         (uint64(DS[3][int((x[1] shr 56) and 0xFF'u64)]) shl 56)) - k[2]
  y[3] = (uint64(DS[0][int(x[3] and 0xFF'u64)]) xor
         (uint64(DS[1][int((x[3] shr 8) and 0xFF'u64)]) shl 8) xor
         (uint64(DS[2][int((x[0] shr 16) and 0xFF'u64)]) shl 16) xor
         (uint64(DS[3][int((x[0] shr 24) and 0xFF'u64)]) shl 24) xor
         (uint64(DS[0][int((x[1] shr 32) and 0xFF'u64)]) shl 32) xor
         (uint64(DS[1][int((x[1] shr 40) and 0xFF'u64)]) shl 40) xor
         (uint64(DS[2][int((x[2] shr 48) and 0xFF'u64)]) shl 48) xor
         (uint64(DS[3][int((x[2] shr 56) and 0xFF'u64)]) shl 56)) - k[3]

template igl512*(x: array[8, uint64], y: var array[8, uint64], k: array[8, uint64]) =
  y[0] = (uint64(DS[0][int(x[0] and 0xFF'u64)]) xor
         (uint64(DS[1][int((x[1] shr 8) and 0xFF'u64)]) shl 8) xor
         (uint64(DS[2][int((x[2] shr 16) and 0xFF'u64)]) shl 16) xor
         (uint64(DS[3][int((x[3] shr 24) and 0xFF'u64)]) shl 24) xor
         (uint64(DS[0][int((x[4] shr 32) and 0xFF'u64)]) shl 32) xor
         (uint64(DS[1][int((x[5] shr 40) and 0xFF'u64)]) shl 40) xor
         (uint64(DS[2][int((x[6] shr 48) and 0xFF'u64)]) shl 48) xor
         (uint64(DS[3][int((x[7] shr 56) and 0xFF'u64)]) shl 56)) - k[0]
  y[1] = (uint64(DS[0][int(x[1] and 0xFF'u64)]) xor
         (uint64(DS[1][int((x[2] shr 8) and 0xFF'u64)]) shl 8) xor
         (uint64(DS[2][int((x[3] shr 16) and 0xFF'u64)]) shl 16) xor
         (uint64(DS[3][int((x[4] shr 24) and 0xFF'u64)]) shl 24) xor
         (uint64(DS[0][int((x[5] shr 32) and 0xFF'u64)]) shl 32) xor
         (uint64(DS[1][int((x[6] shr 40) and 0xFF'u64)]) shl 40) xor
         (uint64(DS[2][int((x[7] shr 48) and 0xFF'u64)]) shl 48) xor
         (uint64(DS[3][int((x[0] shr 56) and 0xFF'u64)]) shl 56)) - k[1]
  y[2] = (uint64(DS[0][int(x[2] and 0xFF'u64)]) xor
         (uint64(DS[1][int((x[3] shr 8) and 0xFF'u64)]) shl 8) xor
         (uint64(DS[2][int((x[4] shr 16) and 0xFF'u64)]) shl 16) xor
         (uint64(DS[3][int((x[5] shr 24) and 0xFF'u64)]) shl 24) xor
         (uint64(DS[0][int((x[6] shr 32) and 0xFF'u64)]) shl 32) xor
         (uint64(DS[1][int((x[7] shr 40) and 0xFF'u64)]) shl 40) xor
         (uint64(DS[2][int((x[0] shr 48) and 0xFF'u64)]) shl 48) xor
         (uint64(DS[3][int((x[1] shr 56) and 0xFF'u64)]) shl 56)) - k[2]
  y[3] = (uint64(DS[0][int(x[3] and 0xFF'u64)]) xor
         (uint64(DS[1][int((x[4] shr 8) and 0xFF'u64)]) shl 8) xor
         (uint64(DS[2][int((x[5] shr 16) and 0xFF'u64)]) shl 16) xor
         (uint64(DS[3][int((x[6] shr 24) and 0xFF'u64)]) shl 24) xor
         (uint64(DS[0][int((x[7] shr 32) and 0xFF'u64)]) shl 32) xor
         (uint64(DS[1][int((x[0] shr 40) and 0xFF'u64)]) shl 40) xor
         (uint64(DS[2][int((x[1] shr 48) and 0xFF'u64)]) shl 48) xor
         (uint64(DS[3][int((x[2] shr 56) and 0xFF'u64)]) shl 56)) - k[3]
  y[4] = (uint64(DS[0][int(x[4] and 0xFF'u64)]) xor
         (uint64(DS[1][int((x[5] shr 8) and 0xFF'u64)]) shl 8) xor
         (uint64(DS[2][int((x[6] shr 16) and 0xFF'u64)]) shl 16) xor
         (uint64(DS[3][int((x[7] shr 24) and 0xFF'u64)]) shl 24) xor
         (uint64(DS[0][int((x[0] shr 32) and 0xFF'u64)]) shl 32) xor
         (uint64(DS[1][int((x[1] shr 40) and 0xFF'u64)]) shl 40) xor
         (uint64(DS[2][int((x[2] shr 48) and 0xFF'u64)]) shl 48) xor
         (uint64(DS[3][int((x[3] shr 56) and 0xFF'u64)]) shl 56)) - k[4]
  y[5] = (uint64(DS[0][int(x[5] and 0xFF'u64)]) xor
         (uint64(DS[1][int((x[6] shr 8) and 0xFF'u64)]) shl 8) xor
         (uint64(DS[2][int((x[7] shr 16) and 0xFF'u64)]) shl 16) xor
         (uint64(DS[3][int((x[0] shr 24) and 0xFF'u64)]) shl 24) xor
         (uint64(DS[0][int((x[1] shr 32) and 0xFF'u64)]) shl 32) xor
         (uint64(DS[1][int((x[2] shr 40) and 0xFF'u64)]) shl 40) xor
         (uint64(DS[2][int((x[3] shr 48) and 0xFF'u64)]) shl 48) xor
         (uint64(DS[3][int((x[4] shr 56) and 0xFF'u64)]) shl 56)) - k[5]
  y[6] = (uint64(DS[0][int(x[6] and 0xFF'u64)]) xor
         (uint64(DS[1][int((x[7] shr 8) and 0xFF'u64)]) shl 8) xor
         (uint64(DS[2][int((x[0] shr 16) and 0xFF'u64)]) shl 16) xor
         (uint64(DS[3][int((x[1] shr 24) and 0xFF'u64)]) shl 24) xor
         (uint64(DS[0][int((x[2] shr 32) and 0xFF'u64)]) shl 32) xor
         (uint64(DS[1][int((x[3] shr 40) and 0xFF'u64)]) shl 40) xor
         (uint64(DS[2][int((x[4] shr 48) and 0xFF'u64)]) shl 48) xor
         (uint64(DS[3][int((x[5] shr 56) and 0xFF'u64)]) shl 56)) - k[6]
  y[7] = (uint64(DS[0][int(x[7] and 0xFF'u64)]) xor
         (uint64(DS[1][int((x[0] shr 8) and 0xFF'u64)]) shl 8) xor
         (uint64(DS[2][int((x[1] shr 16) and 0xFF'u64)]) shl 16) xor
         (uint64(DS[3][int((x[2] shr 24) and 0xFF'u64)]) shl 24) xor
         (uint64(DS[0][int((x[3] shr 32) and 0xFF'u64)]) shl 32) xor
         (uint64(DS[1][int((x[4] shr 40) and 0xFF'u64)]) shl 40) xor
         (uint64(DS[2][int((x[5] shr 48) and 0xFF'u64)]) shl 48) xor
         (uint64(DS[3][int((x[6] shr 56) and 0xFF'u64)]) shl 56)) - k[7]

template g128Key*(x: array[2, uint64], y: var array[2, uint64], k: array[2, uint64]) =
  y[0] = k[0] xor ET[0][int(x[0] and 0xFF'u64)] xor ET[1][int((x[0] shr 8) and 0xFF'u64)] xor ET[2][int((x[0] shr 16) and 0xFF'u64)] xor ET[3][int((x[0] shr 24) and 0xFF'u64)] xor ET[4][int((x[1] shr 32) and 0xFF'u64)] xor ET[5][int((x[1] shr 40) and 0xFF'u64)] xor ET[6][int((x[1] shr 48) and 0xFF'u64)] xor ET[7][int((x[1] shr 56) and 0xFF'u64)]
  y[1] = k[1] xor ET[0][int(x[1] and 0xFF'u64)] xor ET[1][int((x[1] shr 8) and 0xFF'u64)] xor ET[2][int((x[1] shr 16) and 0xFF'u64)] xor ET[3][int((x[1] shr 24) and 0xFF'u64)] xor ET[4][int((x[0] shr 32) and 0xFF'u64)] xor ET[5][int((x[0] shr 40) and 0xFF'u64)] xor ET[6][int((x[0] shr 48) and 0xFF'u64)] xor ET[7][int((x[0] shr 56) and 0xFF'u64)]

template g256Key*(x: array[4, uint64], y: var array[4, uint64], k: array[4, uint64]) =
  y[0] = k[0] xor ET[0][int(x[0] and 0xFF'u64)] xor ET[1][int((x[0] shr 8) and 0xFF'u64)] xor ET[2][int((x[3] shr 16) and 0xFF'u64)] xor ET[3][int((x[3] shr 24) and 0xFF'u64)] xor ET[4][int((x[2] shr 32) and 0xFF'u64)] xor ET[5][int((x[2] shr 40) and 0xFF'u64)] xor ET[6][int((x[1] shr 48) and 0xFF'u64)] xor ET[7][int((x[1] shr 56) and 0xFF'u64)]
  y[1] = k[1] xor ET[0][int(x[1] and 0xFF'u64)] xor ET[1][int((x[1] shr 8) and 0xFF'u64)] xor ET[2][int((x[0] shr 16) and 0xFF'u64)] xor ET[3][int((x[0] shr 24) and 0xFF'u64)] xor ET[4][int((x[3] shr 32) and 0xFF'u64)] xor ET[5][int((x[3] shr 40) and 0xFF'u64)] xor ET[6][int((x[2] shr 48) and 0xFF'u64)] xor ET[7][int((x[2] shr 56) and 0xFF'u64)]
  y[2] = k[2] xor ET[0][int(x[2] and 0xFF'u64)] xor ET[1][int((x[2] shr 8) and 0xFF'u64)] xor ET[2][int((x[1] shr 16) and 0xFF'u64)] xor ET[3][int((x[1] shr 24) and 0xFF'u64)] xor ET[4][int((x[0] shr 32) and 0xFF'u64)] xor ET[5][int((x[0] shr 40) and 0xFF'u64)] xor ET[6][int((x[3] shr 48) and 0xFF'u64)] xor ET[7][int((x[3] shr 56) and 0xFF'u64)])
  y[3] = k[3] xor ET[0][int(x[3] and 0xFF'u64)] xor ET[1][int((x[3] shr 8) and 0xFF'u64)] xor ET[2][int((x[2] shr 16) and 0xFF'u64)] xor ET[3][int((x[2] shr 24) and 0xFF'u64)] xor ET[4][int((x[1] shr 32) and 0xFF'u64)] xor ET[5][int((x[1] shr 40) and 0xFF'u64)] xor ET[6][int((x[0] shr 48) and 0xFF'u64)] xor ET[7][int((x[0] shr 56) and 0xFF'u64)]

template g512Key*(x: array[8, uint64], y: var array[8, uint64], k: array[8, uint64]) =
  y[0] = k[0] xor ET[0][int(x[0] and 0xFF'u64)] xor ET[1][int((x[7] shr 8) and 0xFF'u64)] xor ET[2][int((x[6] shr 16) and 0xFF'u64)] xor ET[3][int((x[5] shr 24) and 0xFF'u64)] xor ET[4][int((x[4] shr 32) and 0xFF'u64)] xor ET[5][int((x[3] shr 40) and 0xFF'u64)] xor ET[6][int((x[2] shr 48) and 0xFF'u64)] xor ET[7][int((x[1] shr 56) and 0xFF'u64)]
  y[1] = k[1] xor ET[0][int(x[1] and 0xFF'u64)] xor ET[1][int((x[0] shr 8) and 0xFF'u64)] xor ET[2][int((x[7] shr 16) and 0xFF'u64)] xor ET[3][int((x[6] shr 24) and 0xFF'u64)] xor ET[4][int((x[5] shr 32) and 0xFF'u64)] xor ET[5][int((x[4] shr 40) and 0xFF'u64)] xor ET[6][int((x[3] shr 48) and 0xFF'u64)] xor ET[7][int((x[2] shr 56) and 0xFF'u64)]
  y[2] = k[2] xor ET[0][int(x[2] and 0xFF'u64)] xor ET[1][int((x[1] shr 8) and 0xFF'u64)] xor ET[2][int((x[0] shr 16) and 0xFF'u64)] xor ET[3][int((x[7] shr 24) and 0xFF'u64)] xor ET[4][int((x[6] shr 32) and 0xFF'u64)] xor ET[5][int((x[5] shr 40) and 0xFF'u64)] xor ET[6][int((x[4] shr 48) and 0xFF'u64)] xor ET[7][int((x[3] shr 56) and 0xFF'u64)]
  y[3] = k[3] xor ET[0][int(x[3] and 0xFF'u64)] xor ET[1][int((x[2] shr 8) and 0xFF'u64)] xor ET[2][int((x[1] shr 16) and 0xFF'u64)] xor ET[3][int((x[0] shr 24) and 0xFF'u64)] xor ET[4][int((x[7] shr 32) and 0xFF'u64)] xor ET[5][int((x[6] shr 40) and 0xFF'u64)] xor ET[6][int((x[5] shr 48) and 0xFF'u64)] xor ET[7][int((x[4] shr 56) and 0xFF'u64)]
  y[4] = k[4] xor ET[0][int(x[4] and 0xFF'u64)] xor ET[1][int((x[3] shr 8) and 0xFF'u64)] xor ET[2][int((x[2] shr 16) and 0xFF'u64)] xor ET[3][int((x[1] shr 24) and 0xFF'u64)] xor ET[4][int((x[0] shr 32) and 0xFF'u64)] xor ET[5][int((x[7] shr 40) and 0xFF'u64)] xor ET[6][int((x[6] shr 48) and 0xFF'u64)] xor ET[7][int((x[5] shr 56) and 0xFF'u64)]
  y[5] = k[5] xor ET[0][int(x[5] and 0xFF'u64)] xor ET[1][int((x[4] shr 8) and 0xFF'u64)] xor ET[2][int((x[3] shr 16) and 0xFF'u64)] xor ET[3][int((x[2] shr 24) and 0xFF'u64)] xor ET[4][int((x[1] shr 32) and 0xFF'u64)] xor ET[5][int((x[0] shr 40) and 0xFF'u64)] xor ET[6][int((x[7] shr 48) and 0xFF'u64)] xor ET[7][int((x[6] shr 56) and 0xFF'u64)]
  y[6] = k[6] xor ET[0][int(x[6] and 0xFF'u64)] xor ET[1][int((x[5] shr 8) and 0xFF'u64)] xor ET[2][int((x[4] shr 16) and 0xFF'u64)] xor ET[3][int((x[3] shr 24) and 0xFF'u64)] xor ET[4][int((x[2] shr 32) and 0xFF'u64)] xor ET[5][int((x[1] shr 40) and 0xFF'u64)] xor ET[6][int((x[0] shr 48) and 0xFF'u64)] xor ET[7][int((x[7] shr 56) and 0xFF'u64)]
  y[7] = k[7] xor ET[0][int(x[7] and 0xFF'u64)] xor ET[1][int((x[6] shr 8) and 0xFF'u64)] xor ET[2][int((x[5] shr 16) and 0xFF'u64)] xor ET[3][int((x[4] shr 24) and 0xFF'u64)] xor ET[4][int((x[3] shr 32) and 0xFF'u64)] xor ET[5][int((x[2] shr 40) and 0xFF'u64)] xor ET[6][int((x[1] shr 48) and 0xFF'u64)] xor ET[7][int((x[0] shr 56) and 0xFF'u64)]

