template b0(x: uint64): int = int(x and 0xff'u64)
template b1(x: uint64): int = int((x shr 8) and 0xff'u64)
template b2(x: uint64): int = int((x shr 16) and 0xff'u64)
template b3(x: uint64): int = int((x shr 24) and 0xff'u64)
template b4(x: uint64): int = int((x shr 32) and 0xff'u64)
template b5(x: uint64): int = int((x shr 40) and 0xff'u64)
template b6(x: uint64): int = int((x shr 48) and 0xff'u64)
template b7(x: uint64): int = int((x shr 56) and 0xff'u64)

proc makeOddKey2(evenkey: array[2, uint64]; oddkey: var array[2, uint64]) =
  # LE MakeOddKey<2>: U=16 V=7 바이트 회전
  var even, odd: array[16, uint8]
  copyMem(addr even[0], unsafeAddr evenkey[0], 16)
  copyMem(addr odd[0], addr even[7], 9)
  copyMem(addr odd[9], addr even[0], 7)
  copyMem(addr oddkey[0], addr odd[0], 16)

proc makeOddKey4(evenkey: array[4, uint64]; oddkey: var array[4, uint64]) =
  var even, odd: array[32, uint8]
  copyMem(addr even[0], unsafeAddr evenkey[0], 32)
  copyMem(addr odd[0], addr even[11], 21)
  copyMem(addr odd[21], addr even[0], 11)
  copyMem(addr oddkey[0], addr odd[0], 32)

proc makeOddKey8(evenkey: array[8, uint64]; oddkey: var array[8, uint64]) =
  var even, odd: array[64, uint8]
  copyMem(addr even[0], unsafeAddr evenkey[0], 64)
  copyMem(addr odd[0], addr even[19], 45)
  copyMem(addr odd[45], addr even[0], 19)
  copyMem(addr oddkey[0], addr odd[0], 64)

# ---- Kalyna-128 ----

type
  Kalyna128Ctx* = object
    rkEnc*: array[30, uint64]  ## 최대 15*2
    rkDec*: array[30, uint64]
    nk*: int  ## 2 또는 4

template setKey16(roundKey: var openArray[uint64], key: array[2, uint64], forward: bool) =
  var ks, ksc, t1, t2, k, kswapped: array[2, uint64]
  zeroMem(addr t1[0], 16)
  t1[0] = (128 + 128 + 64) div 64
  addKey2(t1, t2, key)
  g128(t2, t1, key)
  gl128(t1, t2, key)
  g0128(t2, ks)

  var constant = 0x0001000100010001'u64
  copyMem(addr k[0], unsafeAddr key[0], 16)
  kswapped[1] = k[0]
  kswapped[0] = k[1]

  addConstant2(ks, ksc, constant)
  addKey2(k, t2, ksc)
  g128(t2, t1, ksc)
  block:
    var outk: array[2, uint64]
    gl128(t1, outk, ksc)
    rkeys[0] = outk[0]; rkeys[1] = outk[1]
  block:
    var odd: array[2, uint64]
    makeOddKey2([rkeys[0], rkeys[1]], odd)
    rkeys[2] = odd[0]; rkeys[3] = odd[1]

  constant = constant shl 1
  addConstant2(ks, ksc, constant)
  addKey2(kswapped, t2, ksc)
  g128(t2, t1, ksc)
  block:
    var outk: array[2, uint64]
    gl128(t1, outk, ksc)
    rkeys[4] = outk[0]; rkeys[5] = outk[1]
  block:
    var odd: array[2, uint64]
    makeOddKey2([rkeys[4], rkeys[5]], odd)
    rkeys[6] = odd[0]; rkeys[7] = odd[1]

  constant = constant shl 1
  addConstant2(ks, ksc, constant)
  addKey2(k, t2, ksc)
  g128(t2, t1, ksc)
  block:
    var outk: array[2, uint64]
    gl128(t1, outk, ksc)
    rkeys[8] = outk[0]; rkeys[9] = outk[1]
  block:
    var odd: array[2, uint64]
    makeOddKey2([rkeys[8], rkeys[9]], odd)
    rkeys[10] = odd[0]; rkeys[11] = odd[1]

  constant = constant shl 1
  addConstant2(ks, ksc, constant)
  addKey2(kswapped, t2, ksc)
  g128(t2, t1, ksc)
  block:
    var outk: array[2, uint64]
    gl128(t1, outk, ksc)
    rkeys[12] = outk[0]; rkeys[13] = outk[1]
  block:
    var odd: array[2, uint64]
    makeOddKey2([rkeys[12], rkeys[13]], odd)
    rkeys[14] = odd[0]; rkeys[15] = odd[1]

  constant = constant shl 1
  addConstant2(ks, ksc, constant)
  addKey2(k, t2, ksc)
  g128(t2, t1, ksc)
  block:
    var outk: array[2, uint64]
    gl128(t1, outk, ksc)
    rkeys[16] = outk[0]; rkeys[17] = outk[1]
  block:
    var odd: array[2, uint64]
    makeOddKey2([rkeys[16], rkeys[17]], odd)
    rkeys[18] = odd[0]; rkeys[19] = odd[1]

  constant = constant shl 1
  addConstant2(ks, ksc, constant)
  addKey2(kswapped, t2, ksc)
  g128(t2, t1, ksc)
  block:
    var outk: array[2, uint64]
    gl128(t1, outk, ksc)
    rkeys[20] = outk[0]; rkeys[21] = outk[1]

  if not forward:
    for offset in [18, 16, 14, 12, 10, 8, 6, 4, 2]:
      var pair: array[2, uint64] = [rkeys[offset], rkeys[offset + 1]]
      imc128(pair)
      rkeys[offset] = pair[0]; rkeys[offset + 1] = pair[1]

template kpair(rkeys: openArray[uint64]; offset: int): array[2, uint64] =
  [rkeys[offset], rkeys[offset + 1]]

template processEnc22(rkeys: openArray[uint64]; input, output: array[16, uint8]) =
  block:
    var msg: array[2, uint64] = [loadLE64(input, 0), loadLE64(input, 8)]
    var t1, t2: array[2, uint64]
    addKey2(msg, t1, rkeys)
    var kp = kpair(rkeys, 2); g128(t1, t2, kp)
    kp = kpair(rkeys, 4); g128(t2, t1, kp)
    kp = kpair(rkeys, 6); g128(t1, t2, kp)
    kp = kpair(rkeys, 8); g128(t2, t1, kp)
    kp = kpair(rkeys, 10); g128(t1, t2, kp)
    kp = kpair(rkeys, 12); g128(t2, t1, kp)
    kp = kpair(rkeys, 14); g128(t1, t2, kp)
    kp = kpair(rkeys, 16); g128(t2, t1, kp)
    kp = kpair(rkeys, 18); g128(t1, t2, kp)
    kp = kpair(rkeys, 20); gl128(t2, t1, kp)
    var outb: array[16, uint8]
    storeLE64(outb, 0, t1[0]); storeLE64(outb, 8, t1[1])
    copyMem(addr output[0], addr outb[0], 16)

template processDec22(rkeys: openArray[uint64]; input, output: array[16, uint8]) =
  block:
    var msg: array[2, uint64] = [loadLE64(input, 0), loadLE64(input, 8)]
    var t1, t2: array[2, uint64]
    var kp = kpair(rkeys, 20); subKey2(msg, t1, kp)
    imc128(t1)
    kp = kpair(rkeys, 18); ig128(t1, t2, kp)
    kp = kpair(rkeys, 16); ig128(t2, t1, kp)
    kp = kpair(rkeys, 14); ig128(t1, t2, kp)
    kp = kpair(rkeys, 12); ig128(t2, t1, kp)
    kp = kpair(rkeys, 10); ig128(t1, t2, kp)
    kp = kpair(rkeys, 8); ig128(t2, t1, kp)
    kp = kpair(rkeys, 6); ig128(t1, t2, kp)
    kp = kpair(rkeys, 4); ig128(t2, t1, kp)
    kp = kpair(rkeys, 2); ig128(t1, t2, kp)
    kp = kpair(rkeys, 0); igl128(t2, t1, kp)
    var outb: array[16, uint8]
    storeLE64(outb, 0, t1[0]); storeLE64(outb, 8, t1[1])
    copyMem(addr output[0], addr outb[0], 16)

proc setKey24(rkeys: var openArray[uint64]; key: array[4, uint64]; forward: bool) =
  ## Crypto++ Kalyna128::Base::SetKey_24와 동일
  var ks, ksc, t1, t2: array[2, uint64]
  var k: array[4, uint64]
  var ka, ko: array[2, uint64]
  zeroMem(addr t1[0], 16)
  t1[0] = (128 + 256 + 64) div 64
  ka[0] = key[0]; ka[1] = key[1]
  ko[0] = key[2]; ko[1] = key[3]
  addKey2(t1, t2, ka)
  g128(t2, t1, ko)
  gl128(t1, t2, ka)
  g0128(t2, ks)

  var constant = 0x0001000100010001'u64
  copyMem(addr k[0], unsafeAddr key[0], 32)

  template doEvenRound(dst: int; keyOff: int; withOdd: bool) =
    addConstant2(ks, ksc, constant)
    block:
      var ksrc: array[2, uint64] = [k[keyOff], k[keyOff+1]]
      addKey2(ksrc, t2, ksc)
    g128(t2, t1, ksc)
    block:
      var outk: array[2, uint64]
      gl128(t1, outk, ksc)
      rkeys[dst] = outk[0]; rkeys[dst+1] = outk[1]
    if withOdd:
      var odd: array[2, uint64]
      makeOddKey2([rkeys[dst], rkeys[dst+1]], odd)
      rkeys[dst+2] = odd[0]; rkeys[dst+3] = odd[1]

  doEvenRound(0, 0, true)           # 라운드 0
  constant = constant shl 1
  doEvenRound(4, 2, true)           # 라운드 2
  swapBlocks4(k)
  constant = constant shl 1
  doEvenRound(8, 0, true)           # 라운드 4
  constant = constant shl 1
  doEvenRound(12, 2, true)          # 라운드 6
  swapBlocks4(k)
  constant = constant shl 1
  doEvenRound(16, 0, true)          # 라운드 8
  constant = constant shl 1
  doEvenRound(20, 2, true)          # 라운드 10
  swapBlocks4(k)
  constant = constant shl 1
  doEvenRound(24, 0, true)          # 라운드 12
  constant = constant shl 1
  doEvenRound(28, 2, false)         # 라운드 14 (홀수 없음)

  if not forward:
    for off in [26, 24, 22, 20, 18, 16, 14, 12, 10, 8, 6, 4, 2]:
      var pair: array[2, uint64] = [rkeys[off], rkeys[off+1]]
      imc128(pair)
      rkeys[off] = pair[0]; rkeys[off+1] = pair[1]

template processEnc24(rkeys: openArray[uint64]; input, output: array[16, uint8]) =
  block:
    var msg: array[2, uint64] = [loadLE64(input, 0), loadLE64(input, 8)]
    var t1, t2: array[2, uint64]
    addKey2(msg, t1, rkeys)
    var kp = kpair(rkeys, 2); g128(t1, t2, kp)
    kp = kpair(rkeys, 4); g128(t2, t1, kp)
    kp = kpair(rkeys, 6); g128(t1, t2, kp)
    kp = kpair(rkeys, 8); g128(t2, t1, kp)
    kp = kpair(rkeys, 10); g128(t1, t2, kp)
    kp = kpair(rkeys, 12); g128(t2, t1, kp)
    kp = kpair(rkeys, 14); g128(t1, t2, kp)
    kp = kpair(rkeys, 16); g128(t2, t1, kp)
    kp = kpair(rkeys, 18); g128(t1, t2, kp)
    kp = kpair(rkeys, 20); g128(t2, t1, kp)
    kp = kpair(rkeys, 22); g128(t1, t2, kp)
    kp = kpair(rkeys, 24); g128(t2, t1, kp)
    kp = kpair(rkeys, 26); g128(t1, t2, kp)
    kp = kpair(rkeys, 28); gl128(t2, t1, kp)
    var outb: array[16, uint8]
    storeLE64(outb, 0, t1[0]); storeLE64(outb, 8, t1[1])
    copyMem(addr output[0], addr outb[0], 16)

template processDec24(rkeys: openArray[uint64]; input, output: array[16, uint8]) =
  block:
    var msg: array[2, uint64] = [loadLE64(input, 0), loadLE64(input, 8)]
    var t1, t2: array[2, uint64]
    var kp = kpair(rkeys, 28); subKey2(msg, t1, kp)
    imc128(t1)
    kp = kpair(rkeys, 26); ig128(t1, t2, kp)
    kp = kpair(rkeys, 24); ig128(t2, t1, kp)
    kp = kpair(rkeys, 22); ig128(t1, t2, kp)
    kp = kpair(rkeys, 20); ig128(t2, t1, kp)
    kp = kpair(rkeys, 18); ig128(t1, t2, kp)
    kp = kpair(rkeys, 16); ig128(t2, t1, kp)
    kp = kpair(rkeys, 14); ig128(t1, t2, kp)
    kp = kpair(rkeys, 12); ig128(t2, t1, kp)
    kp = kpair(rkeys, 10); ig128(t1, t2, kp)
    kp = kpair(rkeys, 8); ig128(t2, t1, kp)
    kp = kpair(rkeys, 6); ig128(t1, t2, kp)
    kp = kpair(rkeys, 4); ig128(t2, t1, kp)
    kp = kpair(rkeys, 2); ig128(t1, t2, kp)
    kp = kpair(rkeys, 0); igl128(t2, t1, kp)
    var outb: array[16, uint8]
    storeLE64(outb, 0, t1[0]); storeLE64(outb, 8, t1[1])
    copyMem(addr output[0], addr outb[0], 16)

template kalyna128InitC*[N: static int](ctx: var Kalyna128Ctx; key: array[N, uint8]): void =
  when N != 16 and N != 32:
    {.error: "Kalyna-128 key must be 16 or 32 bytes".}
  zeroMem(addr ctx, sizeof(ctx))
  when N == 16:
    ctx.nk = 2
    var kw: array[2, uint64] = [loadLE64(key, 0), loadLE64(key, 8)]
    setKey22(ctx.rkEnc, kw, true)
    setKey22(ctx.rkDec, kw, false)
  else:
    ctx.nk = 4
    var kw: array[4, uint64]
    for i in 0..3: kw[i] = loadLE64(key, i*8)
    setKey24(ctx.rkEnc, kw, true)
    setKey24(ctx.rkDec, kw, false)

template kalyna128EncryptC*[N: static int](ctx: Kalyna128Ctx; input, output: array[16, uint8]): void =
  discard N
  if ctx.nk == 2:
    processEnc22(ctx.rkEnc, input, output)
  else:
    processEnc24(ctx.rkEnc, input, output)

template kalyna128DecryptC*[N: static int](ctx: Kalyna128Ctx; input, output: array[16, uint8]): void =
  discard N
  if ctx.nk == 2:
    processDec22(ctx.rkDec, input, output)
  else:
    processDec24(ctx.rkDec, input, output)

# ---- Kalyna-256 ----

type
  Kalyna256Ctx* = object
    rkEnc*: array[76, uint64]  ## 최대 19*4
    rkDec*: array[76, uint64]
    nk*: int  ## 4 또는 8

proc load4(rkeys: openArray[uint64]; off: int): array[4, uint64] =
  [rkeys[off], rkeys[off+1], rkeys[off+2], rkeys[off+3]]

proc store4(rkeys: var openArray[uint64]; off: int; v: array[4, uint64]) =
  for i in 0..3: rkeys[off+i] = v[i]

proc setKey44(rkeys: var openArray[uint64]; key: array[4, uint64]; forward: bool) =
  var ks, ksc, t1, t2, k: array[4, uint64]
  zeroMem(addr t1[0], 32)
  t1[0] = (256 + 256 + 64) div 64
  addKey4(t1, t2, key)
  g256(t2, t1, key)
  gl256(t1, t2, key)
  g0256(t2, ks)
  var constant = 0x0001000100010001'u64
  k = key
  template round4(dst: int; withOdd: bool) =
    addConstant4(ks, ksc, constant)
    addKey4(k, t2, ksc)
    g256(t2, t1, ksc)
    block:
      var outk: array[4, uint64]
      gl256(t1, outk, ksc)
      store4(rkeys, dst, outk)
    if withOdd:
      var odd: array[4, uint64]
      makeOddKey4(load4(rkeys, dst), odd)
      store4(rkeys, dst+4, odd)
  round4(0, true)
  for dst in [8, 16, 24, 32, 40, 48]:
    swapBlocks4(k)
    constant = constant shl 1
    round4(dst, true)
  swapBlocks4(k)
  constant = constant shl 1
  round4(56, false)
  if not forward:
    for off in [52, 48, 44, 40, 36, 32, 28, 24, 20, 16, 12, 8, 4]:
      var pair = load4(rkeys, off)
      imc256(pair)
      store4(rkeys, off, pair)

proc setKey48(rkeys: var openArray[uint64]; key: array[8, uint64]; forward: bool) =
  var ks, ksc, t1, t2: array[4, uint64]
  var k: array[8, uint64]
  var ka, ko: array[4, uint64]
  zeroMem(addr t1[0], 32)
  t1[0] = (512 + 256 + 64) div 64
  for i in 0..3: ka[i] = key[i]; ko[i] = key[i+4]
  addKey4(t1, t2, ka)
  g256(t2, t1, ko)
  gl256(t1, t2, ka)
  g0256(t2, ks)
  var constant = 0x0001000100010001'u64
  k = key
  template round48(dst, keyOff: int; withOdd: bool) =
    addConstant4(ks, ksc, constant)
    block:
      var ksrc: array[4, uint64]
      for i in 0..3: ksrc[i] = k[keyOff+i]
      addKey4(ksrc, t2, ksc)
    g256(t2, t1, ksc)
    block:
      var outk: array[4, uint64]
      gl256(t1, outk, ksc)
      store4(rkeys, dst, outk)
    if withOdd:
      var odd: array[4, uint64]
      makeOddKey4(load4(rkeys, dst), odd)
      store4(rkeys, dst+4, odd)
  round48(0, 0, true)
  constant = constant shl 1; round48(8, 4, true)
  swapBlocks8(k); constant = constant shl 1; round48(16, 0, true)
  constant = constant shl 1; round48(24, 4, true)
  swapBlocks8(k); constant = constant shl 1; round48(32, 0, true)
  constant = constant shl 1; round48(40, 4, true)
  swapBlocks8(k); constant = constant shl 1; round48(48, 0, true)
  constant = constant shl 1; round48(56, 4, true)
  swapBlocks8(k); constant = constant shl 1; round48(64, 0, true)
  constant = constant shl 1; round48(72, 4, false)
  if not forward:
    for off in [68, 64, 60, 56, 52, 48, 44, 40, 36, 32, 28, 24, 20, 16, 12, 8, 4]:
      var pair = load4(rkeys, off)
      imc256(pair)
      store4(rkeys, off, pair)

template k4(rkeys: openArray[uint64]; off: int): array[4, uint64] =
  [rkeys[off], rkeys[off+1], rkeys[off+2], rkeys[off+3]]

template processEnc44(rkeys: openArray[uint64]; input, output: array[32, uint8]) =
  block:
    var msg: array[4, uint64]
    for i in 0..3: msg[i] = loadLE64(input, i*8)
    var t1, t2: array[4, uint64]
    addKey4(msg, t1, rkeys)
    var kp = k4(rkeys, 4); g256(t1, t2, kp)
    kp = k4(rkeys, 8); g256(t2, t1, kp)
    kp = k4(rkeys, 12); g256(t1, t2, kp)
    kp = k4(rkeys, 16); g256(t2, t1, kp)
    kp = k4(rkeys, 20); g256(t1, t2, kp)
    kp = k4(rkeys, 24); g256(t2, t1, kp)
    kp = k4(rkeys, 28); g256(t1, t2, kp)
    kp = k4(rkeys, 32); g256(t2, t1, kp)
    kp = k4(rkeys, 36); g256(t1, t2, kp)
    kp = k4(rkeys, 40); g256(t2, t1, kp)
    kp = k4(rkeys, 44); g256(t1, t2, kp)
    kp = k4(rkeys, 48); g256(t2, t1, kp)
    kp = k4(rkeys, 52); g256(t1, t2, kp)
    kp = k4(rkeys, 56); gl256(t2, t1, kp)
    var outb: array[32, uint8]
    for i in 0..3: storeLE64(outb, i*8, t1[i])
    copyMem(addr output[0], addr outb[0], 32)

template processDec44(rkeys: openArray[uint64]; input, output: array[32, uint8]) =
  block:
    var msg: array[4, uint64]
    for i in 0..3: msg[i] = loadLE64(input, i*8)
    var t1, t2: array[4, uint64]
    var kp = k4(rkeys, 56); subKey4(msg, t1, kp)
    imc256(t1)
    kp = k4(rkeys, 52); ig256(t1, t2, kp)
    kp = k4(rkeys, 48); ig256(t2, t1, kp)
    kp = k4(rkeys, 44); ig256(t1, t2, kp)
    kp = k4(rkeys, 40); ig256(t2, t1, kp)
    kp = k4(rkeys, 36); ig256(t1, t2, kp)
    kp = k4(rkeys, 32); ig256(t2, t1, kp)
    kp = k4(rkeys, 28); ig256(t1, t2, kp)
    kp = k4(rkeys, 24); ig256(t2, t1, kp)
    kp = k4(rkeys, 20); ig256(t1, t2, kp)
    kp = k4(rkeys, 16); ig256(t2, t1, kp)
    kp = k4(rkeys, 12); ig256(t1, t2, kp)
    kp = k4(rkeys, 8); ig256(t2, t1, kp)
    kp = k4(rkeys, 4); ig256(t1, t2, kp)
    kp = k4(rkeys, 0); igl256(t2, t1, kp)
    var outb: array[32, uint8]
    for i in 0..3: storeLE64(outb, i*8, t1[i])
    copyMem(addr output[0], addr outb[0], 32)

template processEnc48(rkeys: openArray[uint64]; input, output: array[32, uint8]) =
  block:
    var msg: array[4, uint64]
    for i in 0..3: msg[i] = loadLE64(input, i*8)
    var t1, t2: array[4, uint64]
    addKey4(msg, t1, rkeys)
    var kp = k4(rkeys, 4); g256(t1, t2, kp)
    kp = k4(rkeys, 8); g256(t2, t1, kp)
    kp = k4(rkeys, 12); g256(t1, t2, kp)
    kp = k4(rkeys, 16); g256(t2, t1, kp)
    kp = k4(rkeys, 20); g256(t1, t2, kp)
    kp = k4(rkeys, 24); g256(t2, t1, kp)
    kp = k4(rkeys, 28); g256(t1, t2, kp)
    kp = k4(rkeys, 32); g256(t2, t1, kp)
    kp = k4(rkeys, 36); g256(t1, t2, kp)
    kp = k4(rkeys, 40); g256(t2, t1, kp)
    kp = k4(rkeys, 44); g256(t1, t2, kp)
    kp = k4(rkeys, 48); g256(t2, t1, kp)
    kp = k4(rkeys, 52); g256(t1, t2, kp)
    kp = k4(rkeys, 56); g256(t2, t1, kp)
    kp = k4(rkeys, 60); g256(t1, t2, kp)
    kp = k4(rkeys, 64); g256(t2, t1, kp)
    kp = k4(rkeys, 68); g256(t1, t2, kp)
    kp = k4(rkeys, 72); gl256(t2, t1, kp)
    var outb: array[32, uint8]
    for i in 0..3: storeLE64(outb, i*8, t1[i])
    copyMem(addr output[0], addr outb[0], 32)

template processDec48(rkeys: openArray[uint64]; input, output: array[32, uint8]) =
  block:
    var msg: array[4, uint64]
    for i in 0..3: msg[i] = loadLE64(input, i*8)
    var t1, t2: array[4, uint64]
    var kp = k4(rkeys, 72); subKey4(msg, t1, kp)
    imc256(t1)
    kp = k4(rkeys, 68); ig256(t1, t2, kp)
    kp = k4(rkeys, 64); ig256(t2, t1, kp)
    kp = k4(rkeys, 60); ig256(t1, t2, kp)
    kp = k4(rkeys, 56); ig256(t2, t1, kp)
    kp = k4(rkeys, 52); ig256(t1, t2, kp)
    kp = k4(rkeys, 48); ig256(t2, t1, kp)
    kp = k4(rkeys, 44); ig256(t1, t2, kp)
    kp = k4(rkeys, 40); ig256(t2, t1, kp)
    kp = k4(rkeys, 36); ig256(t1, t2, kp)
    kp = k4(rkeys, 32); ig256(t2, t1, kp)
    kp = k4(rkeys, 28); ig256(t1, t2, kp)
    kp = k4(rkeys, 24); ig256(t2, t1, kp)
    kp = k4(rkeys, 20); ig256(t1, t2, kp)
    kp = k4(rkeys, 16); ig256(t2, t1, kp)
    kp = k4(rkeys, 12); ig256(t1, t2, kp)
    kp = k4(rkeys, 8); ig256(t2, t1, kp)
    kp = k4(rkeys, 4); ig256(t1, t2, kp)
    kp = k4(rkeys, 0); igl256(t2, t1, kp)
    var outb: array[32, uint8]
    for i in 0..3: storeLE64(outb, i*8, t1[i])
    copyMem(addr output[0], addr outb[0], 32)

template kalyna256InitC*[N: static int](ctx: var Kalyna256Ctx; key: array[N, uint8]): void =
  when N != 32 and N != 64:
    {.error: "Kalyna-256 key must be 32 or 64 bytes".}
  zeroMem(addr ctx, sizeof(ctx))
  when N == 32:
    ctx.nk = 4
    var kw: array[4, uint64]
    for i in 0..3: kw[i] = loadLE64(key, i*8)
    setKey44(ctx.rkEnc, kw, true)
    setKey44(ctx.rkDec, kw, false)
  else:
    ctx.nk = 8
    var kw: array[8, uint64]
    for i in 0..7: kw[i] = loadLE64(key, i*8)
    setKey48(ctx.rkEnc, kw, true)
    setKey48(ctx.rkDec, kw, false)

template kalyna256EncryptC*[N: static int](ctx: Kalyna256Ctx; input, output: array[32, uint8]): void =
  discard N
  if ctx.nk == 4: processEnc44(ctx.rkEnc, input, output)
  else: processEnc48(ctx.rkEnc, input, output)

template kalyna256DecryptC*[N: static int](ctx: Kalyna256Ctx; input, output: array[32, uint8]): void =
  discard N
  if ctx.nk == 4: processDec44(ctx.rkDec, input, output)
  else: processDec48(ctx.rkDec, input, output)

# ---- Kalyna-512 ----

type
  Kalyna512Ctx* = object
    rkEnc*: array[152, uint64]  ## 19*8
    rkDec*: array[152, uint64]

proc load8(rkeys: openArray[uint64]; off: int): array[8, uint64] =
  result = [rkeys[off], rkeys[off+1], rkeys[off+2], rkeys[off+3], rkeys[off+4], rkeys[off+5], rkeys[off+6], rkeys[off+7]]

proc store8(rkeys: var openArray[uint64]; off: int; v: array[8, uint64]) =
  for i in 0..7: rkeys[off+i] = v[i]

proc setKey88(rkeys: var openArray[uint64]; key: array[8, uint64]; forward: bool) =
  var ks, ksc, t1, t2, k: array[8, uint64]
  zeroMem(addr t1[0], 64)
  t1[0] = (512 + 512 + 64) div 64
  addKey8(t1, t2, key)
  g512(t2, t1, key)
  gl512(t1, t2, key)
  g0512(t2, ks)
  var constant = 0x0001000100010001'u64
  k = key
  template round88(dst: int; withOdd: bool) =
    addConstant8(ks, ksc, constant)
    addKey8(k, t2, ksc)
    g512(t2, t1, ksc)
    block:
      var outk: array[8, uint64]
      gl512(t1, outk, ksc)
      store8(rkeys, dst, outk)
    if withOdd:
      var odd: array[8, uint64]
      makeOddKey8(load8(rkeys, dst), odd)
      store8(rkeys, dst+8, odd)
  round88(0, true)
  for dst in [16, 32, 48, 64, 80, 96, 112, 128]:
    swapBlocks8(k)
    constant = constant shl 1
    round88(dst, true)
  swapBlocks8(k)
  constant = constant shl 1
  round88(144, false)
  if not forward:
    for off in [136, 128, 120, 112, 104, 96, 88, 80, 72, 64, 56, 48, 40, 32, 24, 16, 8]:
      var pair = load8(rkeys, off)
      imc512(pair)
      store8(rkeys, off, pair)

template k8(rkeys: openArray[uint64]; off: int): array[8, uint64] =
  [rkeys[off], rkeys[off+1], rkeys[off+2], rkeys[off+3], rkeys[off+4], rkeys[off+5], rkeys[off+6], rkeys[off+7]]

template processEnc88(rkeys: openArray[uint64]; input, output: array[64, uint8]) =
  block:
    var msg: array[8, uint64]
    for i in 0..7: msg[i] = loadLE64(input, i*8)
    var t1, t2: array[8, uint64]
    addKey8(msg, t1, rkeys)
    var kp = k8(rkeys, 8); g512(t1, t2, kp)
    kp = k8(rkeys, 16); g512(t2, t1, kp)
    kp = k8(rkeys, 24); g512(t1, t2, kp)
    kp = k8(rkeys, 32); g512(t2, t1, kp)
    kp = k8(rkeys, 40); g512(t1, t2, kp)
    kp = k8(rkeys, 48); g512(t2, t1, kp)
    kp = k8(rkeys, 56); g512(t1, t2, kp)
    kp = k8(rkeys, 64); g512(t2, t1, kp)
    kp = k8(rkeys, 72); g512(t1, t2, kp)
    kp = k8(rkeys, 80); g512(t2, t1, kp)
    kp = k8(rkeys, 88); g512(t1, t2, kp)
    kp = k8(rkeys, 96); g512(t2, t1, kp)
    kp = k8(rkeys, 104); g512(t1, t2, kp)
    kp = k8(rkeys, 112); g512(t2, t1, kp)
    kp = k8(rkeys, 120); g512(t1, t2, kp)
    kp = k8(rkeys, 128); g512(t2, t1, kp)
    kp = k8(rkeys, 136); g512(t1, t2, kp)
    kp = k8(rkeys, 144); gl512(t2, t1, kp)
    var outb: array[64, uint8]
    for i in 0..7: storeLE64(outb, i*8, t1[i])
    copyMem(addr output[0], addr outb[0], 64)

template processDec88(rkeys: openArray[uint64]; input, output: array[64, uint8]) =
  block:
    var msg: array[8, uint64]
    for i in 0..7: msg[i] = loadLE64(input, i*8)
    var t1, t2: array[8, uint64]
    var kp = k8(rkeys, 144); subKey8(msg, t1, kp)
    imc512(t1)
    kp = k8(rkeys, 136); ig512(t1, t2, kp)
    kp = k8(rkeys, 128); ig512(t2, t1, kp)
    kp = k8(rkeys, 120); ig512(t1, t2, kp)
    kp = k8(rkeys, 112); ig512(t2, t1, kp)
    kp = k8(rkeys, 104); ig512(t1, t2, kp)
    kp = k8(rkeys, 96); ig512(t2, t1, kp)
    kp = k8(rkeys, 88); ig512(t1, t2, kp)
    kp = k8(rkeys, 80); ig512(t2, t1, kp)
    kp = k8(rkeys, 72); ig512(t1, t2, kp)
    kp = k8(rkeys, 64); ig512(t2, t1, kp)
    kp = k8(rkeys, 56); ig512(t1, t2, kp)
    kp = k8(rkeys, 48); ig512(t2, t1, kp)
    kp = k8(rkeys, 40); ig512(t1, t2, kp)
    kp = k8(rkeys, 32); ig512(t2, t1, kp)
    kp = k8(rkeys, 24); ig512(t1, t2, kp)
    kp = k8(rkeys, 16); ig512(t2, t1, kp)
    kp = k8(rkeys, 8); ig512(t1, t2, kp)
    kp = k8(rkeys, 0); igl512(t2, t1, kp)
    var outb: array[64, uint8]
    for i in 0..7: storeLE64(outb, i*8, t1[i])
    copyMem(addr output[0], addr outb[0], 64)

template kalyna512InitC*[N: static int](ctx: var Kalyna512Ctx; key: array[N, uint8]): void =
  when N != 64:
    {.error: "Kalyna-512 key must be 64 bytes".}
  zeroMem(addr ctx, sizeof(ctx))
  var kw: array[8, uint64]
  for i in 0..7: kw[i] = loadLE64(key, i*8)
  setKey88(ctx.rkEnc, kw, true)
  setKey88(ctx.rkDec, kw, false)

template kalyna512EncryptC*[N: static int](ctx: Kalyna512Ctx; input, output: array[64, uint8]): void =
  discard N
  processEnc88(ctx.rkEnc, input, output)

template kalyna512DecryptC*[N: static int](ctx: Kalyna512Ctx; input, output: array[64, uint8]): void =
  discard N
  processDec88(ctx.rkDec, input, output)
